from crewai import Task
 
from agent.quality_agent import quality_checker
 
 
def create_quality_task(
    event_name,
    event_date,
    audience,
    idea_task,
    activity_task,
    invitation_task
):
 
    quality_task = Task(
 
        description=(
 
            f"Perform a final quality check for the event "
            f"'{event_name}'."
 
            f"The event date is {event_date}."
 
            f"The target audience is {audience}."
 
            "Review the event theme generated by the Idea Generator."
 
            "Check whether exactly four activities are available."
 
            "Check whether the event date is mentioned."
 
            "Check whether the invitation is available."
 
            "Check whether venue information is available."
 
            "Do not invent any missing information."
 
            "If no venue was supplied, mark it as "
            "'To be confirmed'."
 
            "Prepare a final checklist showing "
            "Available and Missing details."
 
        ),
 
        expected_output=(
 
            "A final event quality checklist containing: "
 
            "1. Event theme status "
 
            "2. Four activities status "
 
            "3. Event date status "
 
            "4. Invitation status "
 
            "5. Venue status "
 
            "6. List of missing details"
 
        ),
 
        agent=quality_checker,
 
        context=[
            idea_task,
            activity_task,
            invitation_task
        ]
    )
 
    return quality_task